import '../models/effective_ad_config.dart';
import '../telemetry/ad_telemetry.dart';

/// Initialization options for the WAP Ads SDK.
class WapAdsOptions {
  /// The unique registered application ID in WAPCentral (e.g. 'filezen', 'optilens').
  final String appId;

  /// The public app credential key generated by WAPCentral.
  /// Note: Provider secret keys (AdMob, Meta, AppLovin) are NEVER required in the mobile client.
  final String appKey;

  /// Deployment environment ('production' | 'staging' | 'development').
  final String environment;

  /// WAPCentral backend base URL. Defaults to canonical custom domain endpoint.
  final String baseUrl;

  /// Whether the app is running in developer test mode.
  final bool testMode;

  /// Whether to automatically fetch configuration refreshes in the background.
  final bool autoRefreshConfig;

  /// Time interval between background configuration refreshes.
  final Duration refreshInterval;

  /// Optional initial/cached configuration supplied at startup.
  final EffectiveAdConfig? initialConfig;

  /// Optional initial telemetry listener.
  final AdTelemetryListener? telemetryListener;

  const WapAdsOptions({
    required this.appId,
    required this.appKey,
    this.environment = 'production',
    this.baseUrl = 'https://wapcentral.webappypie.com',
    this.testMode = false,
    this.autoRefreshConfig = true,
    this.refreshInterval = const Duration(minutes: 15),
    this.initialConfig,
    this.telemetryListener,
  });

  /// Factory for testing with mock parameters.
  factory WapAdsOptions.test({
    String appId = 'test_app',
    String appKey = 'wap_key_test',
    String baseUrl = 'http://localhost:8080',
    EffectiveAdConfig? initialConfig,
    AdTelemetryListener? telemetryListener,
  }) {
    return WapAdsOptions(
      appId: appId,
      appKey: appKey,
      environment: 'development',
      baseUrl: baseUrl,
      testMode: true,
      autoRefreshConfig: false,
      initialConfig: initialConfig,
      telemetryListener: telemetryListener,
    );
  }
}

/// Environment constants for WAP Ads initialization.
abstract class WapEnvironment {
  static const String production = 'production';
  static const String staging = 'staging';
  static const String development = 'development';
}
